using System; using System.Drawing; using System.Linq; using System.Threading.Tasks; using System.Windows.Forms; using ChimeraEmailExtractor.Core;
namespace ChimeraEmailExtractor.UI { public class MainForm:Form { readonly TextBox urls=new(){Multiline=true,Dock=DockStyle.Top,Height=70}; readonly ProgressBar pages=new(),contacts=new(),overall=new(); readonly DataGridView grid=new(); readonly Button search=new(){Text="Search Now"}; public MainForm(){Text="Chimera Email Extractor";Width=900;Height=600;grid.Dock=DockStyle.Fill;grid.Columns.Add("Email","Email Address");grid.Columns.Add("Title","Page Title");grid.Columns.Add("Website","Website");grid.Columns.Add("MX","MX");var p=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=45};p.Controls.Add(search);Controls.Add(grid);Controls.Add(p);Controls.Add(overall);Controls.Add(contacts);Controls.Add(pages);Controls.Add(urls);search.Click+=async(_,_)=>await RunAsync();} async Task RunAsync(){var list=urls.Lines.Where(x=>!string.IsNullOrWhiteSpace(x)).ToArray();pages.Maximum=100;overall.Maximum=100;for(int i=0;i<list.Length;i++){var r=await Extractor.FetchPage(list[i]);foreach(var e in Extractor.ExtractEmails(r.Html))grid.Rows.Add(e,ExtractTitle(r.Html),r.FinalUrl,Extractor.ValidateEmail(e)?"YES":"NO");pages.Value=(i+1)*100/Math.Max(1,list.Length);overall.Value=pages.Value;contacts.Value=Math.Min(100,grid.Rows.Count);} } static string ExtractTitle(string html){var a=html.IndexOf("<title",StringComparison.OrdinalIgnoreCase);if(a<0)return "";a=html.IndexOf('>',a);var b=html.IndexOf("</title>",a,StringComparison.OrdinalIgnoreCase);return b>a?System.Net.WebUtility.HtmlDecode(html[(a+1)..b].Trim()):"";} [STAThread]public static void Main(){ApplicationConfiguration.Initialize();Application.Run(new MainForm());}}}
